// Exact finite polynomial-matrix certificate; no formal-tail extrapolation.
#include <flint/fmpq.h>
#include <flint/fmpq_poly.h>
#include <flint/fmpq_mat.h>
#include <flint/fmpz_poly.h>
#include <vector>
#include <fstream>
#include <iostream>
#include <cassert>
#include <chrono>
using namespace std;
struct Poly{fmpq_poly_t p;Poly(){fmpq_poly_init(p);}Poly(const Poly&a):Poly(){fmpq_poly_set(p,a.p);}Poly(Poly&&a):Poly(){fmpq_poly_swap(p,a.p);}Poly&operator=(Poly a){fmpq_poly_swap(p,a.p);return *this;}~Poly(){fmpq_poly_clear(p);}};
void normalize(vector<Poly*> line){fmpz_t L,G,d,m,c;fmpz_init(L);fmpz_init(G);fmpz_init(d);fmpz_init(m);fmpz_init(c);fmpz_one(L);fmpz_poly_t N;fmpz_poly_init(N);for(auto p:line){fmpq_poly_get_denominator(d,p->p);fmpz_lcm(L,L,d);}for(auto p:line){fmpq_poly_get_numerator(N,p->p);fmpz_poly_content(c,N);fmpq_poly_get_denominator(d,p->p);fmpz_divexact(m,L,d);fmpz_mul(c,c,m);fmpz_gcd(G,G,c);}if(!fmpz_is_zero(G)){fmpq_t q;fmpq_init(q);fmpq_set_fmpz_frac(q,L,G);for(auto p:line)fmpq_poly_scalar_mul_fmpq(p->p,p->p,q);fmpq_clear(q);}fmpz_poly_clear(N);fmpz_clear(L);fmpz_clear(G);fmpz_clear(d);fmpz_clear(m);fmpz_clear(c);}
void normalizeAll(vector<vector<Poly>>&A){int n=A.size();for(int i=0;i<n;i++){vector<Poly*>line;for(int j=0;j<n;j++)line.push_back(&A[i][j]);normalize(line);}for(int j=0;j<n;j++){vector<Poly*>line;for(int i=0;i<n;i++)line.push_back(&A[i][j]);normalize(line);}}
int main(int argc,char**argv){assert(argc==4);ifstream config(argv[3]);string root;int steps,target;config>>root>>steps>>target;vector<int>expected(steps);for(int&x:expected)config>>x;assert(config);ifstream in(argv[1]);ofstream out(argv[2]);int nr,n;in>>nr>>n;assert(nr==n);vector<vector<Poly>>A(n,vector<Poly>(n));vector<int>rowdegrees(n);fmpq_t q,shift;fmpq_init(q);fmpq_init(shift);assert(!fmpq_set_str(shift,root.c_str(),10));fmpq_canonicalise(shift);Poly shiftpoly;fmpq_poly_set_coeff_fmpq(shiftpoly.p,0,shift);fmpq_poly_set_coeff_si(shiftpoly.p,1,1);long bound=0;for(int i=0;i<n;i++){int nz;in>>nz;for(int k=0;k<nz;k++){int j,len;in>>j>>len;rowdegrees[i]=max(rowdegrees[i],len-1);for(int e=0;e<len;e++){string s;in>>s;assert(!fmpq_set_str(q,s.c_str(),10));fmpq_canonicalise(q);fmpq_poly_set_coeff_fmpq(A[i][j].p,e,q);}}for(int j=0;j<n;j++){Poly b;fmpq_poly_compose(b.p,A[i][j].p,shiftpoly.p);A[i][j]=std::move(b);fmpq_poly_truncate(A[i][j].p,steps);}bound+=rowdegrees[i];}normalizeAll(A);fmpq_mat_t R;fmpq_mat_init(R,n,n);long valuation=0;auto st=chrono::steady_clock::now();for(int step=0;step<steps;step++){for(int i=0;i<n;i++)for(int j=0;j<n;j++)fmpq_poly_get_coeff_fmpq(fmpq_mat_entry(R,i,j),A[i][j].p,0);int rank=fmpq_mat_rref(R,R);double sec=chrono::duration<double>(chrono::steady_clock::now()-st).count();out<<"STEP "<<step<<" RANK "<<rank<<" VALUATION "<<valuation<<" SEC "<<sec<<'\n';out.flush();cerr<<"STEP "<<step<<" RANK "<<rank<<" VAL "<<valuation<<" SEC "<<sec<<'\n';assert(rank==expected[step]);valuation+=n-rank;if(step==steps-1){assert(valuation==target);out<<"ROOT_BOUND_AUX "<<bound-valuation<<" TROPICAL_ROW_BOUND "<<bound<<" VALUATION "<<valuation<<'\n';break;}vector<int>piv;vector<bool>used(n);for(int i=0;i<rank;i++){int j=0;while(fmpq_is_zero(fmpq_mat_entry(R,i,j)))j++;piv.push_back(j);used[j]=true;}for(int j=0;j<n;j++)if(!used[j]){fmpz_t den;fmpz_init(den);fmpz_one(den);for(int k=0;k<rank;k++)fmpz_lcm(den,den,fmpq_denref(fmpq_mat_entry(R,k,j)));fmpq_t anchor,c;fmpq_init(anchor);fmpq_init(c);fmpq_set_fmpz(anchor,den);for(int i=0;i<n;i++){Poly b,z;fmpq_poly_scalar_mul_fmpq(b.p,A[i][j].p,anchor);for(int k=0;k<rank;k++){fmpq_mul(c,fmpq_mat_entry(R,k,j),anchor);assert(fmpz_is_one(fmpq_denref(c)));if(!fmpq_is_zero(c)){fmpq_poly_scalar_mul_fmpq(z.p,A[i][piv[k]].p,c);fmpq_poly_sub(b.p,b.p,z.p);}}fmpq_poly_get_coeff_fmpq(q,b.p,0);assert(fmpq_is_zero(q));fmpq_poly_shift_right(A[i][j].p,b.p,1);}fmpq_clear(anchor);fmpq_clear(c);fmpz_clear(den);}normalizeAll(A);for(int ii=0;ii<n;ii++)for(int jj=0;jj<n;jj++)fmpq_poly_truncate(A[ii][jj].p,steps-1-step);}
fmpq_clear(q);fmpq_clear(shift);fmpq_mat_clear(R);}
